create extension if not exists pgcrypto;create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,email text,role text not null default 'customer',created_at timestamptz default now());create table if not exists public.products(id uuid primary key default gen_random_uuid(),name text not null,description text,price numeric(12,2) not null default 0,category text,image_url text,stock integer not null default 0,is_active boolean not null default true,created_at timestamptz default now());create table if not exists public.posts(id uuid primary key default gen_random_uuid(),title text not null,content text,image_url text,is_published boolean not null default true,created_at timestamptz default now());create table if not exists public.orders(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,total_amount numeric(12,2) not null,items jsonb not null default '[]',status text not null default 'pending',created_at timestamptz default now());create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,email) values(new.id,new.email) on conflict(id) do nothing;return new;end;$$;drop trigger if exists on_auth_user_created on auth.users;create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();alter table public.profiles enable row level security;alter table public.products enable row level security;alter table public.posts enable row level security;alter table public.orders enable row level security;create policy "public products" on public.products for select using(is_active=true);create policy "public posts" on public.posts for select using(is_published=true);create policy "own profile" on public.profiles for select using(auth.uid()=id);create policy "own orders read" on public.orders for select using(auth.uid()=user_id);create policy "own orders insert" on public.orders for insert with check(auth.uid()=user_id);create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='admin');$$;create policy "admin products" on public.products for all using(public.is_admin()) with check(public.is_admin());create policy "admin posts" on public.posts for all using(public.is_admin()) with check(public.is_admin());create policy "admin profiles" on public.profiles for select using(auth.uid()=id or public.is_admin());create policy "admin orders" on public.orders for select using(auth.uid()=user_id or public.is_admin());